//! Port of Go's `regexp/syntax/perl_groups.go` (generated by make_perl_groups.pl): the ASCII
//! Perl (`\d \s \w`) and POSIX (`[:alnum:]` …) classes.

use go_unicode::Rune;

/// Go: `charGroup`.
#[derive(Clone, Copy)]
pub(crate) struct CharGroup {
    pub sign: i32,
    pub class: &'static [Rune],
}

static CODE1: [Rune; 2] = [0x30, 0x39]; // \d
static CODE2: [Rune; 6] = [0x9, 0xa, 0xc, 0xd, 0x20, 0x20]; // \s
static CODE3: [Rune; 8] = [0x30, 0x39, 0x41, 0x5a, 0x5f, 0x5f, 0x61, 0x7a]; // \w

/// Go: `perlGroup[s]` (`sign == 0`: not a Perl class).
pub(crate) fn perl_group(s: &[u8]) -> Option<CharGroup> {
    let (sign, class): (i32, &'static [Rune]) = match s {
        br"\d" => (1, &CODE1),
        br"\D" => (-1, &CODE1),
        br"\s" => (1, &CODE2),
        br"\S" => (-1, &CODE2),
        br"\w" => (1, &CODE3),
        br"\W" => (-1, &CODE3),
        _ => return None,
    };
    Some(CharGroup { sign, class })
}

static CODE4: [Rune; 6] = [0x30, 0x39, 0x41, 0x5a, 0x61, 0x7a]; // [:alnum:]
static CODE5: [Rune; 4] = [0x41, 0x5a, 0x61, 0x7a]; // [:alpha:]
static CODE6: [Rune; 2] = [0x0, 0x7f]; // [:ascii:]
static CODE7: [Rune; 4] = [0x9, 0x9, 0x20, 0x20]; // [:blank:]
static CODE8: [Rune; 4] = [0x0, 0x1f, 0x7f, 0x7f]; // [:cntrl:]
static CODE9: [Rune; 2] = [0x30, 0x39]; // [:digit:]
static CODE10: [Rune; 2] = [0x21, 0x7e]; // [:graph:]
static CODE11: [Rune; 2] = [0x61, 0x7a]; // [:lower:]
static CODE12: [Rune; 2] = [0x20, 0x7e]; // [:print:]
static CODE13: [Rune; 8] = [0x21, 0x2f, 0x3a, 0x40, 0x5b, 0x60, 0x7b, 0x7e]; // [:punct:]
static CODE14: [Rune; 4] = [0x9, 0xd, 0x20, 0x20]; // [:space:]
static CODE15: [Rune; 2] = [0x41, 0x5a]; // [:upper:]
static CODE16: [Rune; 8] = [0x30, 0x39, 0x41, 0x5a, 0x5f, 0x5f, 0x61, 0x7a]; // [:word:]
static CODE17: [Rune; 6] = [0x30, 0x39, 0x41, 0x46, 0x61, 0x66]; // [:xdigit:]

/// Go: `posixGroup[name]`.
pub(crate) fn posix_group(name: &[u8]) -> Option<CharGroup> {
    let (neg, base) = match name.strip_prefix(b"[:^") {
        Some(rest) => (true, rest),
        None => (false, name.strip_prefix(b"[:")?),
    };
    let class: &'static [Rune] = match base {
        b"alnum:]" => &CODE4,
        b"alpha:]" => &CODE5,
        b"ascii:]" => &CODE6,
        b"blank:]" => &CODE7,
        b"cntrl:]" => &CODE8,
        b"digit:]" => &CODE9,
        b"graph:]" => &CODE10,
        b"lower:]" => &CODE11,
        b"print:]" => &CODE12,
        b"punct:]" => &CODE13,
        b"space:]" => &CODE14,
        b"upper:]" => &CODE15,
        b"word:]" => &CODE16,
        b"xdigit:]" => &CODE17,
        _ => return None,
    };
    Some(CharGroup {
        sign: if neg { -1 } else { 1 },
        class,
    })
}
